import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CstmrAccountUpdateParams } from '~/entities/user/model/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const updateCstmrAccount = (tbCstmrMastr: CstmrAccountUpdateParams) => {
  return resultify(
    axios.post<any>(API_URLS.getCommonUrl(`acnutUpdate`), {
      tbCstmrMastr,
    }),
  );
};

export const useUpdateCstmrAccountMutation = (
  options?: MutationOptions<CstmrAccountUpdateParams, CBDCAxiosError, CstmrAccountUpdateParams>,
) => {
  const mutation = useMutation<CstmrAccountUpdateParams, CBDCAxiosError, CstmrAccountUpdateParams>({
    ...options,
    mutationFn: (tbCstmrMastr: CstmrAccountUpdateParams) => updateCstmrAccount(tbCstmrMastr),
  });

  return {
    ...mutation,
  };
};
