import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { ArsRequest, ConfirmUserResponse } from '~/entities/pin/api/dtos/types';
import { UserParams } from '~/entities/user/api/dtos/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

const arsNumber1 = (tbCstmrMastr: Partial<UserParams>) => {
  return resultify(axios.post<ConfirmUserResponse>(`${API_URLS.getCommonUrl('ars1')}`, tbCstmrMastr));
};
const arsNumber2 = (ars: ArsRequest) => {
  return resultify(axios.post<ConfirmUserResponse>(`${API_URLS.getCommonUrl('ars2')}`, ars));
};

export const useArsNumber1Mutation = (
  options?: MutationOptions<Partial<UserParams>, CBDCAxiosError, ConfirmUserResponse>,
) => {
  const mutation = useMutation<ConfirmUserResponse, CBDCAxiosError, Partial<UserParams>>({
    ...options,
    mutationFn: (tbCstmrMastr: Partial<UserParams>) => arsNumber1(tbCstmrMastr),
  });

  return {
    ...mutation,
  };
};
export const useArsNumber2Mutation = (options?: MutationOptions<ArsRequest, CBDCAxiosError, ConfirmUserResponse>) => {
  const mutation = useMutation<ConfirmUserResponse, CBDCAxiosError, ArsRequest>({
    ...options,
    mutationFn: (ars: ArsRequest) => arsNumber2(ars),
  });

  return {
    ...mutation,
  };
};
